#!/usr/bin/env python3
"""Regenerates the live GitHub plate (plate-dark.svg / plate-light.svg).
Data comes from the GitHub REST API using GITHUB_TOKEN when available,
or from stats-data.json next to this script (local preview)."""
import json, os, sys, urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
USER = "Dongdarealest"

def fetch():
    cache = os.path.join(HERE, "stats-data.json")
    if os.path.exists(cache) and os.environ.get("USE_CACHE"):
        return json.load(open(cache))
    token = os.environ.get("GITHUB_TOKEN", "")
    def get(path):
        req = urllib.request.Request("https://api.github.com" + path, headers={"Authorization": f"Bearer {token}", "Accept": "application/vnd.github+json", "User-Agent": "profile-stats"})
        return json.load(urllib.request.urlopen(req))
    user = get(f"/users/{USER}")
    repos = get(f"/users/{USER}/repos?per_page=100&sort=updated")
    own = [r for r in repos if not r["fork"]]
    langs = {}
    for r in own:
        if r.get("language"): langs[r["language"]] = langs.get(r["language"], 0) + 1
    try: release = get(f"/repos/{USER}/skillport/releases/latest")["tag_name"]
    except Exception: release = ""
    return {"repos": user["public_repos"], "followers": user["followers"],
            "stars": sum(r["stargazers_count"] for r in own),
            "langs": sorted(langs.items(), key=lambda kv: -kv[1])[:5],
            "recent": [{"name": r["name"], "stars": r["stargazers_count"], "updated": r["updated_at"][:10]} for r in own[:3]],
            "release": release}

