def esc(s): return s.replace("&", "&amp;").replace("<", "&lt;")

def plate(d, dark):
    bg = "#0B0B0C" if dark else "#F5F2EA"; ink = "#F0EDE6" if dark else "#121214"
    mut = "#8A8680" if dark else "#6E6A62"; gold = "#C9A35F"; line = "#2A2A2C" if dark else "#D8D2C4"
    W, H = 1240, 452
    total_lang = sum(n for _, n in d["langs"]) or 1
    segs, x = "", 64
    colors = ["#C9A35F", "#8A8680", "#5C584F", "#3E3C36", "#29271F"] if dark else ["#A98B4F", "#8A8680", "#B4AEA0", "#CFC9BA", "#E2DDD0"]
    for i, (name, n) in enumerate(d["langs"]):
        w = max(30, int((W - 128) * n / total_lang))
        segs += f'<rect x="{x}" y="212" width="{w - 4}" height="6" fill="{colors[i]}"/>'
        segs += f'<text x="{x}" y="248" font-family="Helvetica, Arial, sans-serif" font-size="19" letter-spacing="2" fill="{mut}">{esc(name).upper()}</text>'
        x += w
    recent = ""
    for i, r in enumerate(d["recent"]):
        y = 316 + i * 38
        recent += f'<text x="64" y="{y}" font-family="Georgia, serif" font-style="italic" font-size="25" fill="{ink}">{esc(r["name"])}</text>'
        recent += f'<text x="{64 + len(r["name"]) * 13 + 26}" y="{y}" font-family="Helvetica, Arial, sans-serif" font-size="19" fill="{mut}">updated {r["updated"]} · {r["stars"]} stars</text>'
    stats = ""
    for i, (big, small) in enumerate([(str(d["repos"]), "PUBLIC PROJECTS"), (str(d["stars"]), "STARS EARNED"), (str(d["followers"]), "FOLLOWERS")]):
        x = 64 + i * 380
        stats += f'<text x="{x}" y="128" font-family="Georgia, serif" font-size="58" fill="{ink}">{big}</text>'
        stats += f'<text x="{x + 2}" y="164" font-family="Helvetica, Arial, sans-serif" font-size="17" letter-spacing="3" fill="{mut}">{small}</text>'
    return f'''<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}">
<rect width="{W}" height="{H}" rx="18" fill="{bg}"/>
<text x="64" y="58" font-family="Helvetica, Arial, sans-serif" font-size="18" letter-spacing="5" fill="{gold}">LIVE FROM GITHUB</text>
<text x="{W - 64}" y="58" text-anchor="end" font-family="Helvetica, Arial, sans-serif" font-size="18" letter-spacing="3" fill="{mut}">SKILLPORT {esc(d["release"])}</text>
<line x1="64" y1="80" x2="{W - 64}" y2="80" stroke="{line}" stroke-width="1"/>
{stats}{segs}
<text x="64" y="288" font-family="Helvetica, Arial, sans-serif" font-size="17" letter-spacing="3" fill="{mut}">RECENTLY ACTIVE</text>
{recent}
<text x="{W - 64}" y="{H - 24}" text-anchor="end" font-family="Helvetica, Arial, sans-serif" font-size="15" letter-spacing="2" fill="{mut}">UPDATED AUTOMATICALLY, EVERY DAY</text>
</svg>'''

LANG_ICON = {"Python": ("python", "Python"), "JavaScript": ("javascript", "JavaScript"), "HTML": ("html5", "HTML"), "CSS": ("css3", "CSS"), "PHP": ("php", "PHP"), "TypeScript": ("javascript", "TypeScript")}
EXTRA_TOOLS = [("googlechrome", "Chrome extensions"), ("githubactions", "GitHub Actions"), ("git", "Git")]

def tools_plate(d, dark):
    fill = "#B8B2A4" if dark else "#55524A"
    mut = "#8A8680" if dark else "#6E6A62"
    tools = []
    for name, _n in d["langs"]:
        if name in LANG_ICON: tools.append(LANG_ICON[name])
    tools += EXTRA_TOOLS
    tools = tools[:8]
    W = 1240; H = 168; step = W // max(len(tools), 1)
    parts = []
    for i, (slug, label) in enumerate(tools):
        cx = step * i + step // 2
        path = ICONS.get(slug, "")
        parts.append(f'<g transform="translate({cx - 27},26) scale(2.25)"><path d="{path}" fill="{fill}"/></g>')
        parts.append(f'<text x="{cx}" y="128" text-anchor="middle" font-family="Helvetica, Arial, sans-serif" font-size="16" letter-spacing="0" fill="{mut}">{label}</text>')
    return f'''<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}">{"".join(parts)}</svg>'''

def write_tools(d):
    open(os.path.join(HERE, "tools-dark.svg"), "w").write(tools_plate(d, True))
    open(os.path.join(HERE, "tools-light.svg"), "w").write(tools_plate(d, False))

def contrib_plate(dark):
    cache = json.load(open(os.path.join(HERE, "contrib-cache.json")))
    weeks = cache["weeks"]; total = cache["total"]
    active = sum(1 for w in weeks for day in w if day["c"] > 0)
    if dark:
        empty, label, mut = "#1C1C1F", "#F5F2EA", "#8A8680"
        lv = ["#4A3F28", "#7A6535", "#A98B4F", "#E3C888"]
    else:
        empty, label, mut = "#E9E5DB", "#141414", "#6E6A62"
        lv = ["#D8C491", "#B99B57", "#A98B4F", "#7A6535"]
    mx = max(day["c"] for w in weeks for day in w) or 1
    def lvl(c):
        if c == 0: return empty
        q = c / mx
        return lv[0] if q <= .25 else lv[1] if q <= .5 else lv[2] if q <= .75 else lv[3]
    cell, gap = 15, 4
    W = len(weeks) * (cell + gap) + 8
    H = 7 * (cell + gap) + 74
    parts = [f'<text x="4" y="26" font-family="Georgia, serif" font-size="24" fill="{label}">{total} contributions in the last year</text>']
    parts.append(f'<text x="4" y="52" font-family="Helvetica, Arial, sans-serif" font-size="14" letter-spacing="2" fill="{mut}">{active} ACTIVE DAYS · UPDATED FROM REAL CONTRIBUTIONS</text>')
    for wi, w in enumerate(weeks):
        for di, day in enumerate(w):
            x = 4 + wi * (cell + gap); y = 66 + di * (cell + gap)
            parts.append(f'<rect x="{x}" y="{y}" width="{cell}" height="{cell}" rx="3" fill="{lvl(day["c"])}"><title>{day["d"]}: {day["c"]}</title></rect>')
    return f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}">{"".join(parts)}</svg>'

def write_contrib():
    open(os.path.join(HERE, "contrib-dark.svg"), "w").write(contrib_plate(True))
    open(os.path.join(HERE, "contrib-light.svg"), "w").write(contrib_plate(False))

if __name__ == "__main__":
    d = fetch()
    open(os.path.join(HERE, "plate-dark.svg"), "w").write(plate(d, True))
    open(os.path.join(HERE, "plate-light.svg"), "w").write(plate(d, False))
    write_tools(d)
    write_contrib()
    print("plates written", d["repos"], "repos,", d["stars"], "stars")
